// Optional, separately identified subjects for each funds scope/direction.
(()=>{const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];all('[id="pb-meeting"],[data-meeting]').forEach(e=>e.remove());all('button').filter(e=>/discuss my eligibility/i.test(e.textContent)).forEach(e=>e.remove());let seq=0;
function add(host,data={}){const row=document.createElement('div');row.className='repeat counterparty-record';row.dataset.recordId=data.id||'party-'+(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+(++seq));const grid=document.createElement('div');grid.className='grid';for(const [key,title]of [['name','Registered entity name or individual full name'],['kind','Counterparty type'],['country','Country'],['relationship','Relationship']]){const l=document.createElement('label');l.className='field';const span=document.createElement('span');span.textContent=title;let e;if(key==='kind'||key==='country'){e=document.createElement('select');e.add(new Option('Select…',''));(key==='kind'?['Legal entity','Individual']:countryNames).forEach(v=>e.add(new Option(v,v)));}else e=document.createElement('input');e.dataset.partyField=key;e.value=data[key]||'';e.required=true;l.append(span,e);grid.append(l);}const remove=document.createElement('button');remove.type='button';remove.className='mini';remove.textContent='Remove counterparty';remove.onclick=()=>{row.remove();host.dispatchEvent(new Event('change',{bubbles:true}));};row.append(grid,remove);host.querySelector('.counterparty-list').append(row);host.dispatchEvent(new Event('change',{bubbles:true}));return row;}
function block(parent,scope,direction){const host=document.createElement('section');host.className='counterparty-block';host.dataset.fundsScope=scope;host.dataset.counterpartyDirection=direction;host.innerHTML='<h3>Main '+direction+' counterparties (optional)</h3><p class="hint">Add known customers, suppliers or other main counterparties. Leave this section empty if none have been identified yet. Supplied names enter pre-introduction screening.</p><div class="counterparty-list"></div><button class="mini" type="button">+ Add counterparty</button>';host.querySelector('button').onclick=()=>add(host);parent.append(host);return host;}
const banks=q('[data-screen="3"] .grid');if(banks){block(banks.children[0],'bank','incoming');block(banks.children[1],'bank','outgoing');}const pb=q('#pb-regular');if(pb){block(pb,'private','incoming');block(pb,'private','outgoing');}for(const [id,scope]of [['fi-operational-flows','operational'],['fi-client-flows','client']]){const parent=q('#'+id);if(parent){block(parent,scope,'incoming');block(parent,scope,'outgoing');}}
function visible(e){const s=e.closest('.screen');if(!s||!activeFlow().includes(Number(s.dataset.screen)))return false;for(let p=e;p&&p!==s;p=p.parentElement)if(p.hidden)return false;return true;}
window.ApplicantRecords=window.ApplicantRecords||{};ApplicantRecords.counterparties=(includeInactive=false)=>all('.counterparty-block').filter(e=>includeInactive||visible(e)).flatMap(host=>[...host.querySelectorAll('.counterparty-record')].map(row=>({id:row.dataset.recordId,scope:host.dataset.fundsScope,direction:host.dataset.counterpartyDirection,...Object.fromEntries([...row.querySelectorAll('[data-party-field]')].map(e=>[e.dataset.partyField,e.value.trim()]))})));
ApplicantRecords.restoreCounterparties=records=>{all('.counterparty-list').forEach(e=>e.replaceChildren());for(const record of records||[]){const host=q('[data-funds-scope="'+record.scope+'"][data-counterparty-direction="'+record.direction+'"]');if(host)add(host,record);}};
})();


